initJs:
function(container, apiUrl, tables) {
  const tbody = container.querySelector("#inventory-tbody");
  const errorMessage = container.querySelector("#error-message");
  const searchResultMessage = container.querySelector("#search-result-message");
  const storeSelect = container.querySelector("#store-select");

  // 店舗マスタのテーブルインデックスを取得
  const storeTableIndex = tables.findIndex(t => t.tableName === "店舗マスタ");
  const productTableIndex = tables.findIndex(t => t.tableName === "商品マスタ");

  // エラーメッセージ表示関数
  function showError(message) {
    errorMessage.textContent = message;
    errorMessage.classList.remove("hidden");
    setTimeout(() => {
      errorMessage.classList.add("hidden");
    }, 5000);
  }

  // バリデーション関数
  function validateInput() {
    const productName = container.querySelector("#product-name-search").value;
    const productCode = container.querySelector("#product-code-search").value;

    // 商品名の特殊文字チェック
    if (productName && /<script|javascript:|data:|vbscript:|onload=|onerror=/i.test(productName)) {
      showError("商品名に不正な文字が含まれています");
      return false;
    }

    // SQLインジェクション対策
    if (productName && /('|"|;|--|\/\*|\*\/|xp_|sp_|DROP|DELETE|INSERT|UPDATE|SELECT)/i.test(productName)) {
      showError("商品名に使用できない文字が含まれています");
      return false;
    }

    // 商品コードの数値チェック（文字が入力された場合）
    if (productCode && !/^\d*$/.test(productCode)) {
      showError("商品コードは数値で入力してください");
      return false;
    }

    // 商品名の最大文字数チェック
    if (productName && productName.length > 255) {
      showError("商品名は255文字以内で入力してください");
      return false;
    }

    // 商品コードの最大桁数チェック
    if (productCode && productCode.length > 20) {
      showError("商品コードは20桁以内で入力してください");
      return false;
    }

    return true;
  }

  // 在庫状況判定関数
  function getStockStatus(currentStock, safetyStock) {
    if (currentStock === 0) return "不足";
    if (currentStock <= safetyStock) return "不足";
    if (currentStock > safetyStock * 2) return "過剰";
    return "適正";
  }

  // 在庫状況の色分け
  function getStatusColor(status) {
    switch (status) {
      case "不足": return "color: #ff6a6a;";
      case "過剰": return "color: #ffa500;";
      case "適正": return "color: #4caf50;";
      default: return "color: var(--text);";
    }
  }

  // テーブル再描画関数
  function renderRows(inventoryData) {
    if (!inventoryData || inventoryData.length === 0) {
      tbody.innerHTML = "";
      searchResultMessage.textContent = "該当する商品が見つかりませんでした";
      return;
    }

    tbody.innerHTML = inventoryData.map(item => {
      const status = getStockStatus(item.currentStock || 0, item.safetyStock || 0);
      const statusStyle = getStatusColor(status);

      return `
        <tr data-id="${item.id || ''}">
          <td>${item.productCode || ""}</td>
          <td>${item.productName || ""}</td>
          <td>${item.category || ""}</td>
          <td style="${item.currentStock === 0 ? 'color: #ff6a6a; font-weight: bold;' : ''}">${item.currentStock || 0}</td>
          <td>${item.safetyStock || 0}</td>
          <td style="${statusStyle}">${status}</td>
          <td>${item.lastUpdated ? new Date(item.lastUpdated).toLocaleString() : ""}</td>
        </tr>
      `;
    }).join("");

    searchResultMessage.textContent = `${inventoryData.length}件の商品が見つかりました`;
  }

  // 店舗選択肢を設定
  async function loadStores() {
    if (storeTableIndex >= 0) {
      const stores = await window.aivicApi.list(storeTableIndex);
      if (stores) {
        stores.filter(store => store.有効フラグ).forEach(store => {
          const option = document.createElement("option");
          option.value = store.店舗ID;
          option.textContent = `${store.店舗コード} - ${store.店舗名}`;
          storeSelect.appendChild(option);
        });
      }
    }
  }

  // 在庫データ生成（サンプルデータ）
  function generateInventoryData(products, selectedStoreId) {
    return products.map(product => ({
      id: product.商品ID,
      productCode: product.商品コード,
      productName: product.商品名,
      category: getCategoryName(product.商品カテゴリID),
      currentStock: Math.floor(Math.random() * 200),
      safetyStock: Math.floor(Math.random() * 50) + 10,
      lastUpdated: new Date(Date.now() - Math.random() * 7 * 24 * 60 * 60 * 1000).toISOString()
    }));
  }

  function getCategoryName(categoryId) {
    const categories = {
      "cat1": "食品",
      "cat2": "日用品", 
      "cat3": "衣料品",
      "cat4": "家電"
    };
    return categories[categoryId] || "その他";
  }

  // 検索実行
  async function performSearch() {
    const selectedStoreId = storeSelect.value;

    if (!selectedStoreId) {
      showError("店舗を選択してください");
      return;
    }

    if (!validateInput()) {
      return;
    }

    const categoryFilter = container.querySelector("#category-filter").value;
    const productNameSearch = container.querySelector("#product-name-search").value.toLowerCase();
    const productCodeSearch = container.querySelector("#product-code-search").value;
    const stockStatusFilter = container.querySelector("#stock-status-filter").value;

    try {
      // 商品マスタを取得
      const products = await window.aivicApi.list(productTableIndex);
      if (!products) {
        showError("商品データの取得に失敗しました");
        return;
      }

      // 在庫データを生成
      let inventoryData = generateInventoryData(products.filter(p => p.有効フラグ), selectedStoreId);

      // フィルタリング
      if (categoryFilter) {
        inventoryData = inventoryData.filter(item => item.category === categoryFilter);
      }

      if (productNameSearch) {
        inventoryData = inventoryData.filter(item => 
          item.productName.toLowerCase().includes(productNameSearch)
        );
      }

      if (productCodeSearch) {
        inventoryData = inventoryData.filter(item => 
          item.productCode.includes(productCodeSearch)
        );
      }

      if (stockStatusFilter) {
        inventoryData = inventoryData.filter(item => {
          const status = getStockStatus(item.currentStock, item.safetyStock);
          return status === stockStatusFilter;
        });
      }

      renderRows(inventoryData);

    } catch (error) {
      showError("検索処理中にエラーが発生しました");
      console.error("Search error:", error);
    }
  }

  // CSVエクスポート
  function exportToCSV() {
    const selectedStoreId = storeSelect.value;
    if (!selectedStoreId) {
      showError("店舗を選択してください");
      return;
    }

    window.aivicApi.list(productTableIndex).then(products => {
      if (!products) return;

      const inventoryData = generateInventoryData(products.filter(p => p.有効フラグ), selectedStoreId);

      const headers = ["商品コード", "商品名", "商品カテゴリ", "現在在庫数", "安全在庫数", "在庫状況", "最終更新日時"];
      const csvContent = [
        headers.join(","),
        ...inventoryData.map(item => {
          const status = getStockStatus(item.currentStock, item.safetyStock);
          return [
            `"${item.productCode}"`,
            `"${item.productName}"`,
            `"${item.category}"`,
            item.currentStock,
            item.safetyStock,
            `"${status}"`,
            `"${new Date(item.lastUpdated).toLocaleString()}"`
          ].join(",");
        })
      ].join("\n");

      const bom = "\uFEFF";
      const blob = new Blob([bom + csvContent], { type: "text/csv;charset=utf-8;" });
      const link = document.createElement("a");
      link.href = URL.createObjectURL(blob);
      link.download = `在庫一覧_${new Date().toISOString().split('T')[0]}.csv`;
      link.click();
    });
  }

  // 検索条件クリア
  function clearSearchConditions() {
    container.querySelector("#category-filter").value = "";
    container.querySelector("#product-name-search").value = "";
    container.querySelector("#product-code-search").value = "";
    container.querySelector("#stock-status-filter").value = "";
    tbody.innerHTML = "";
    searchResultMessage.textContent = "";
    errorMessage.classList.add("hidden");
  }

  // 初期化
  loadStores();
  renderRows([]);

  // イベントリスナー
  container.querySelector("#btn-search").addEventListener("click", performSearch);
  container.querySelector("#btn-clear").addEventListener("click", clearSearchConditions);
  container.querySelector("#btn-export").addEventListener("click", exportToCSV);

  // Enterキーで検索実行
  container.addEventListener("keypress", (e) => {
    if (e.key === "Enter") {
      performSearch();
    }
  });
}
